234	// =========================================================================
235	//  Occupancy / refuse probe (gate e). The faithful "occupancy >= 1 or refuse"
236	//  contract: query cudaOccupancyMaxActiveBlocksPerMultiprocessor for a given
237	//  dynamic-smem request; if it is 0 the launch would not be resident → REFUSE
238	//  (return 0) WITHOUT launching (no hang). Also exercises the hard failure
239	//  path: a smem request beyond the device max returns
240	//  cudaErrorLaunchOutOfResources promptly (asserted in python).
241	// =========================================================================
242	static int64_t occupancy_for_smem(int64_t requested_smem_bytes) {
243	    int numBlocks = 0;
244	    cudaError_t e = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
245	        &numBlocks, gemm_single_tile_kernel<128>, 128,
246	        (size_t)requested_smem_bytes);
247	    if (e != cudaSuccess) {
248	        // The query itself rejected the config (e.g. > device max): clear the
249	        // sticky error and report 0 occupancy (refuse). No kernel was launched.
250	        cudaGetLastError();
251	        return 0;
252	    }
253	    return (int64_t)numBlocks;
254	}
